CREATE TABLE `app_log` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint DEFAULT NULL COMMENT '上报用户(未登录可空)',
  `level` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'info' COMMENT '级别 info/error',
  `tag` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标签 crash/track:xxx',
  `message` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '摘要信息',
  `stack` text COLLATE utf8mb4_unicode_ci COMMENT '堆栈',
  `app_version` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'App版本号',
  `device` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备描述',
  `creator` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0未删 1已删',
  PRIMARY KEY (`id`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_level` (`level`),
  KEY `idx_user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=297 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='App端日志/埋点';
