--
-- Table structure for table `photo`
--

DROP TABLE IF EXISTS `photo`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `photo` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `spot_id` bigint NOT NULL COMMENT '关联点位(1:N)',
  `user_id` bigint NOT NULL COMMENT '上传用户(关联 user.id)',
  `sso_user_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SSO用户标识(冗余字段,跨服务查询用)',
  `url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '远程原图(旧数据兼容,本地化后新记录为空)',
  `thumb_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '缩略图 URL',
  `local_path` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备本地原图路径',
  `local_thumb_path` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备本地缩略图路径',
  `width` int DEFAULT NULL COMMENT '图片宽度(px)',
  `height` int DEFAULT NULL COMMENT '图片高度(px)',
  `size_bytes` bigint DEFAULT NULL COMMENT '文件大小(byte)',
  `format` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图片格式(jpg/png/webp/heic)',
  `lat` decimal(10,7) NOT NULL COMMENT '拍摄纬度(GCJ-02)',
  `lng` decimal(10,7) NOT NULL COMMENT '拍摄经度(GCJ-02)',
  `geo` point NOT NULL DEFAULT (st_geomfromtext(_utf8mb4'POINT(0 0)')),
  `shot_time` datetime DEFAULT NULL COMMENT '拍摄时间(从 EXIF 读取)',
  `device` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '拍摄设备(EXIF Make + Model)',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户描述/文案',
  `audit_status` tinyint NOT NULL DEFAULT '0' COMMENT '审核状态 0待审 1通过 2驳回',
  `audit_reason` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '驳回原因',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `auditor` bigint DEFAULT NULL COMMENT '审核人(关联 user.id)',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '同点位排序(升序,小的在前)',
  `view_count` int NOT NULL DEFAULT '0' COMMENT '查看次数',
  `like_count` int NOT NULL DEFAULT '0' COMMENT '点赞数(冗余)',
  `is_cover` tinyint NOT NULL DEFAULT '0' COMMENT '是否点位封面 0否 1是',
  `creator` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0未删 1已删',
  PRIMARY KEY (`id`),
  KEY `idx_spot` (`spot_id`),
  KEY `idx_user` (`user_id`),
  KEY `idx_audit` (`audit_status`),
  KEY `idx_sso` (`sso_user_id`),
  KEY `idx_lat_lng` (`lat`,`lng`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_is_cover` (`spot_id`,`is_cover`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='照片表(1:1关联点位,关联SSO)';
/*!40101 SET character_set_client = @saved_cs_client */;

