--
-- Table structure for table `spot`
--

DROP TABLE IF EXISTS `spot`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `spot` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '点位名称',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `category` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分类(scenic/restaurant/viewpoint/activity/other)',
  `tags` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标签 JSON 数组，如 ["花海","日出","网红"]',
  `lat` decimal(10,7) NOT NULL COMMENT '纬度(GCJ-02)',
  `lng` decimal(10,7) NOT NULL COMMENT '经度(GCJ-02)',
  `geo` point NOT NULL DEFAULT (st_geomfromtext(_utf8mb4'POINT(0 0)')),
  `cover_photo_id` bigint DEFAULT NULL COMMENT '封面照片ID(关联 photo 表)',
  `address` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '地址描述',
  `province` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '省(逆地理编码回填)',
  `city` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '市(逆地理编码回填)',
  `district` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '区/县(逆地理编码回填)',
  `photo_count` int NOT NULL DEFAULT '0' COMMENT '关联照片数(冗余字段)',
  `like_count` int NOT NULL DEFAULT '0' COMMENT '点赞数(冗余字段)',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0待审 1上线 2驳回 3下架',
  `creator` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0未删 1已删',
  PRIMARY KEY (`id`),
  SPATIAL KEY `idx_geo` (`geo`),
  KEY `idx_status` (`status`),
  KEY `idx_category` (`category`),
  KEY `idx_city` (`city`),
  KEY `idx_creator` (`creator`),
